305	/// Fuzz decisions read from the input. Exhausted input yields zeros, so a shorter
306	/// input is always a smaller case: truncating is our shrinker.
307	pub const Input = struct {
308	    bytes: []const u8,
309	    pos: usize = 0,
310	
311	    pub fn byte(in: *Input) u8 {
312	        if (in.pos >= in.bytes.len) return 0;
313	        defer in.pos += 1;
314	        return in.bytes[in.pos];
315	    }
316	    /// In [0, n); 0 when n == 0.
317	    pub fn below(in: *Input, n: usize) usize {
318	        if (n == 0) return 0;
319	        return (@as(usize, in.byte()) | @as(usize, in.byte()) << 8) % n;
320	    }
321	    /// Little-endian, zero-padded past the end.
322	    pub fn int(in: *Input, comptime T: type) T {
323	        var buf: [@sizeOf(T)]u8 = @splat(0);
324	        for (&buf) |*b| b.* = in.byte();
325	        return std.mem.readInt(T, &buf, .little);
326	    }
327	    pub fn rest(in: *Input) []const u8 {
328	        const r = in.bytes[@min(in.pos, in.bytes.len)..];
329	        in.pos = in.bytes.len;
330	        return r;
331	    }
