258	/// Executions so far; the watchdog calls a hang when it stops moving for `hang_seconds`.
259	var progress = std.atomic.Value(u64).init(0);
260	var hang_seconds: u64 = 10;
261	
262	fn watchdog(io: std.Io) void {
263	    var last = progress.load(.monotonic);
264	    var still: u64 = 0;
265	    while (true) {
266	        io.sleep(.fromNanoseconds(1_000_000_000), .awake) catch return;
267	        const now = progress.load(.monotonic);
268	        still = if (now == last) still + 1 else 0;
269	        last = now;
270	        if (still >= hang_seconds) {
271	            std.debug.print("fuzz-hang: one input ran for over {d}s: {s}\n", .{ hang_seconds, if (current_path.len > 0) current_path else "<out>/current.bin" });
272	            std.process.exit(77);
273	        }
274	    }
275	}
