317	/// Files directly under `path` (or `path` itself), sorted for a stable order. In directories only
318	/// `.parquet` and `.bin` files count.
319	fn listInputs(a: Allocator, io: std.Io, path: []const u8, out: *std.ArrayList([]const u8)) !void {
320	    var dir = std.Io.Dir.cwd().openDir(io, path, .{ .iterate = true }) catch |e| switch (e) {
321	        error.NotDir => return out.append(a, path),
322	        else => return e,
323	    };
324	    defer dir.close(io);
325	    const start = out.items.len;
326	    var it = dir.iterate();
327	    while (try it.next(io)) |entry| {
328	        if (entry.kind != .file) continue;
329	        if (!std.mem.endsWith(u8, entry.name, ".parquet") and !std.mem.endsWith(u8, entry.name, ".bin")) continue;
330	        try out.append(a, try std.fs.path.join(a, &.{ path, entry.name }));
331	    }
332	    std.mem.sort([]const u8, out.items[start..], {}, struct {
333	        fn lt(_: void, x: []const u8, y: []const u8) bool {
334	            return std.mem.order(u8, x, y) == .lt;
335	        }
336	    }.lt);
337	}
