371	fn run(gpa: Allocator, io: std.Io, target: Target, args: []const []const u8) !void {
372	    var arena_state = std.heap.ArenaAllocator.init(gpa);
373	    defer arena_state.deinit();
374	    const a = arena_state.allocator();
375	    if (args.len < 1) usage();
376	    const budget = args[0];
377	    const by_time = std.mem.endsWith(u8, budget, "s");
378	    const limit = std.fmt.parseInt(u64, if (by_time) budget[0 .. budget.len - 1] else budget, 10) catch usage();
379	    var out_dir: ?[]const u8 = null;
380	    var seed: u64 = @truncate(@as(u96, @bitCast(std.Io.Timestamp.now(io, .real).toNanoseconds())));
381	    var max_len: usize = max_input_len;
382	    var corpus_paths: std.ArrayList([]const u8) = .empty;
383	    var explicit_corpus = false;
384	    var i: usize = 1;
385	    while (i + 1 < args.len) : (i += 2) {
386	        const v = args[i + 1];
387	        if (std.mem.eql(u8, args[i], "--corpus")) {
388	            explicit_corpus = true;
389	            listInputs(a, io, v, &corpus_paths) catch |e| std.debug.print("corpus {s}: {s}\n", .{ v, @errorName(e) });
390	        } else if (std.mem.eql(u8, args[i], "--out")) {
391	            out_dir = v;
392	        } else if (std.mem.eql(u8, args[i], "--seed")) {
393	            seed = std.fmt.parseInt(u64, v, 10) catch usage();
394	        } else if (std.mem.eql(u8, args[i], "--max-len")) {
395	            max_len = @min(std.fmt.parseInt(usize, v, 10) catch usage(), max_input_len);
396	        } else if (std.mem.eql(u8, args[i], "--alloc-cap")) {
397	            alloc_cap = std.fmt.parseInt(usize, v, 10) catch usage();
398	        } else usage();
399	    }
400	    const out = out_dir orelse usage();
401	    const cwd = std.Io.Dir.cwd();
402	    const grow_dir = try std.fs.path.join(a, &.{ out, "corpus" });
403	    try cwd.createDirPath(io, grow_dir);
404	    try listInputs(a, io, grow_dir, &corpus_paths);
405	    const current = try cwd.createFile(io, try std.fs.path.join(a, &.{ out, "current.bin" }), .{ .truncate = true });
406	    defer current.close(io);
407	    var out_handle = try cwd.openDir(io, out, .{});
408	    defer out_handle.close(io);
409	
410	    // Seeds: explicit --corpus dirs, else fuzz/corpus/<target> plus seed_dirs (adapted); then
411	    // what earlier runs grew into <out>/corpus. Inputs that crashed before (<out>/skip/<hash>) are skipped.
412	    var inputs: std.ArrayList([]const u8) = .empty;
413	    if (!explicit_corpus) try inputs.appendSlice(a, try loadSeeds(a, io, target, .raw));
414	    for (corpus_paths.items) |path| {
415	        const bytes = cwd.readFileAlloc(io, path, a, .limited(max_len)) catch continue;
416	        try inputs.append(a, bytes);
417	    }
418	    var corpus: std.ArrayList([]const u8) = .empty;
419	    var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
420	    for (inputs.items) |bytes| {
421	        if (bytes.len > max_len) continue;
422	        const hex = hexName(bytes);
423	        const crash_name = try std.fmt.allocPrint(a, "skip/{s}", .{&hex});
424	        if (out_handle.statFile(io, crash_name, .{})) |_| {
425	            std.debug.print("skipping known crasher {s}\n", .{&hex});
426	            continue;
427	        } else |_| {}
428	        try current.writePositionalAll(io, bytes, 0);
429	        try current.setLength(io, bytes.len);
430	        const fb = runOne(target, gpa, bytes);
431	        _ = progress.fetchAdd(1, .monotonic);
432	        try seen.put(a, fb.sig(), {});
433	        try corpus.append(a, bytes);
434	    }
435	    if (corpus.items.len == 0) try corpus.append(a, "");
436	    std.debug.print("{s}: seed {d}, {d} corpus inputs, {d} signatures\n", .{ @tagName(target), seed, corpus.items.len, seen.count() });
437	
438	    var prng = std.Random.DefaultPrng.init(seed);
439	    const rng = prng.random();
440	    var buf: std.ArrayList(u8) = .empty;
441	    defer buf.deinit(gpa);
442	    const start = std.Io.Timestamp.now(io, .awake);
443	    var iters: u64 = 0;
444	    while (true) : (iters += 1) {
445	        if (iters % 256 == 0) {
446	            const elapsed: u64 = std.math.cast(u64, start.durationTo(std.Io.Timestamp.now(io, .awake)).toSeconds()) orelse 0;
447	            if ((by_time and elapsed >= limit) or (!by_time and iters >= limit)) break;
448	            if (iters % (1 << 14) == 0 and iters > 0)
449	                std.debug.print("#{d} {d}s corpus {d} signatures {d}\n", .{ iters, elapsed, corpus.items.len, seen.count() });
450	        } else if (!by_time and iters >= limit) break;
451	
452	        buf.clearRetainingCapacity();
453	        try buf.appendSlice(gpa, corpus.items[rng.uintLessThan(usize, corpus.items.len)]);
454	        try mutate(rng, gpa, &buf, corpus.items, max_len);
455	        try current.writePositionalAll(io, buf.items, 0);
456	        try current.setLength(io, buf.items.len);
457	        const fb = runOne(target, gpa, buf.items);
458	        _ = progress.fetchAdd(1, .monotonic);
459	        const gop = try seen.getOrPut(a, fb.sig());
460	        // ponytail: fixed corpus cap; signature-based growth has no coverage to prune with.
461	        if (gop.found_existing or corpus.items.len >= max_corpus) continue;
462	        const copy = try a.dupe(u8, buf.items);
463	        try corpus.append(a, copy);
464	        const hex = hexName(copy);
465	        const name = try std.fmt.allocPrint(a, "{s}.bin", .{&hex});
466	        var dir = try cwd.openDir(io, grow_dir, .{});
467	        defer dir.close(io);
468	        try dir.writeFile(io, .{ .sub_path = name, .data = copy });
469	    }
470	    std.debug.print("{s}: done, {d} execs, corpus {d}, {d} signatures\n", .{ @tagName(target), iters, corpus.items.len, seen.count() });
471	}
