532	test "fuzz corpus expectations" {
533	    const gpa = std.testing.allocator;
534	    const io = std.testing.io;
535	    const cwd = std.Io.Dir.cwd();
536	    const text = try cwd.readFileAlloc(io, corpus_root ++ "/expected.txt", gpa, .limited(1 << 20));
537	    defer gpa.free(text);
538	    var lines = std.mem.splitScalar(u8, text, '\n');
539	    while (lines.next()) |raw_line| {
540	        const line = std.mem.trim(u8, raw_line, " \t\r");
541	        if (line.len == 0 or line[0] == '#') continue;
542	        var fields = std.mem.tokenizeAny(u8, line, " \t");
543	        const path = fields.next() orelse continue;
544	        const want = fields.next() orelse return error.BadExpectation;
545	        const slash = std.mem.indexOfScalar(u8, path, '/') orelse return error.BadExpectation;
546	        const target = std.meta.stringToEnum(Target, path[0..slash]) orelse return error.BadExpectation;
547	        const full = try std.fs.path.join(gpa, &.{ corpus_root, path });
548	        defer gpa.free(full);
549	        const bytes = try cwd.readFileAlloc(io, full, gpa, .limited(max_input_len));
550	        defer gpa.free(bytes);
551	        const fb = runOne(target, gpa, bytes);
552	        const ok = if (std.mem.eql(u8, want, "ok"))
553	            fb.err == null
554	        else if (std.mem.eql(u8, want, "error"))
555	            fb.err != null
556	        else if (std.mem.startsWith(u8, want, "error."))
557	            if (fb.err) |e| std.mem.eql(u8, @errorName(e), want["error.".len..]) else false
558	        else
559	            return error.BadExpectation;
560	        if (!ok) {
561	            std.debug.print("expected.txt: {s}: wanted {s}, got {s}\n", .{ path, want, if (fb.err) |e| @errorName(e) else "ok" });
562	            return error.UnexpectedOutcome;
563	        }
564	    }
