37	/// Inputs over this size are skipped (replay) or never produced (run).
38	pub const max_input_len: usize = 64 << 10;
39	/// Live bytes one input may allocate before it counts as an OOM finding.
40	pub var alloc_cap: usize = 256 << 20;
41	/// Print the error return trace of a rejected input (set by single-file replay).
42	var explain = false;
43	/// In-memory corpus cap for `run`; past it, new signatures are still counted but not kept.
