46	// ---------------------------------------------------------------------------------------------
47	// Allocation cap + per-input leak check.
48	
49	const CountingAllocator = struct {
50	    parent: Allocator,
51	    live: usize = 0,
52	
53	    fn allocator(self: *CountingAllocator) Allocator {
54	        return .{ .ptr = self, .vtable = &.{ .alloc = alloc, .resize = resize, .remap = remap, .free = free } };
55	    }
56	
57	    fn charge(self: *CountingAllocator, old: usize, new: usize) void {
58	        if (new > old and self.live + (new - old) > alloc_cap)
59	            std.debug.panic("fuzz-oom: allocation of {d} bytes with {d} live exceeds cap {d}", .{ new - old, self.live, alloc_cap });
60	    }
61	
62	    fn alloc(ctx: *anyopaque, len: usize, a: std.mem.Alignment, ra: usize) ?[*]u8 {
63	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
64	        self.charge(0, len);
65	        const p = self.parent.rawAlloc(len, a, ra) orelse return null;
66	        self.live += len;
67	        return p;
68	    }
69	
70	    fn resize(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, n: usize, ra: usize) bool {
71	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
72	        self.charge(m.len, n);
73	        if (!self.parent.rawResize(m, a, n, ra)) return false;
74	        self.live = self.live - m.len + n;
75	        return true;
76	    }
77	
78	    fn remap(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, n: usize, ra: usize) ?[*]u8 {
79	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
80	        self.charge(m.len, n);
81	        const p = self.parent.rawRemap(m, a, n, ra) orelse return null;
82	        self.live = self.live - m.len + n;
83	        return p;
84	    }
85	
86	    fn free(ctx: *anyopaque, m: []u8, a: std.mem.Alignment, ra: usize) void {
87	        const self: *CountingAllocator = @ptrCast(@alignCast(ctx));
88	        self.parent.rawFree(m, a, ra);
89	        self.live -= m.len;
90	    }
91	};
