93	/// Runs one input against `target`. Panics (= finding) on leaks, cap overruns and broken
94	/// invariants; library errors are returned in the feedback.
95	pub fn runOne(target: Target, parent: Allocator, bytes: []const u8) Feedback {
96	    var counting: CountingAllocator = .{ .parent = parent };
97	    const gpa = counting.allocator();
98	    var fb: Feedback = .{};
99	    const result = switch (target) {
100	        .file => t_file.run(gpa, bytes, &fb, false),
101	        .@"file-oom" => t_file.run(gpa, bytes, &fb, true),
102	        .page => t_page.run(gpa, bytes, &fb),
103	        .encoding => t_encoding.run(gpa, bytes, &fb),
104	        .thrift => t_thrift.run(gpa, bytes, &fb),
105	        .codec => t_codec.run(gpa, bytes, &fb),
106	    };
107	    result catch |e| {
108	        fb.err = e;
109	        // Single-file replay: show where the input was rejected (compat-gap triage).
110	        if (explain) if (@errorReturnTrace()) |trace| std.debug.dumpErrorReturnTrace(trace);
111	    };
112	    if (counting.live != 0) std.debug.panic("fuzz-leak: {d} bytes still allocated after the input", .{counting.live});
113	    return fb;
114	}
