119	/// Turns a seed file into an input for `target`, or null if it does not apply.
120	/// .parquet seeds: file/file-oom take the bytes as they are (file-oom prepends two 0xff bytes =
121	/// no injected failure); thrift takes the footer (bytes between the 4-byte length and "PAR1")
122	/// with the prefix `ff ff 00 00` (no failure, which = FileMetaData); others skip.
123	/// .bin files (fuzz/corpus/<target>/) are already in target format.
124	fn adaptSeed(target: Target, name: []const u8, bytes: []const u8, out: Allocator) !?[]const u8 {
125	    if (std.mem.endsWith(u8, name, ".bin")) return try out.dupe(u8, bytes);
126	    if (!std.mem.endsWith(u8, name, ".parquet")) return null;
127	    switch (target) {
128	        .file => return try out.dupe(u8, bytes),
129	        .@"file-oom" => return try std.mem.concat(out, u8, &.{ &.{ 0xff, 0xff }, bytes }),
130	        .thrift => {
131	            if (bytes.len < 12 or !std.mem.eql(u8, bytes[bytes.len - 4 ..], "PAR1")) return null;
132	            const flen: usize = std.mem.readInt(u32, bytes[bytes.len - 8 ..][0..4], .little);
133	            if (flen > bytes.len - 12) return null;
134	            const footer = bytes[bytes.len - 8 - flen ..][0..flen];
135	            return try std.mem.concat(out, u8, &.{ &.{ 0xff, 0xff, 0x00, 0x00 }, footer });
136	        },
137	        .page, .encoding, .codec => return null,
138	    }
139	}
