141	pub const SeedFormat = enum { raw, smith_encoded };
142	
143	/// Every adapted seed for `target`: fuzz/corpus/<target>/*.bin first, then `seed_dirs`. Missing
144	/// directories and unreadable or oversized files are skipped. `smith_encoded` prefixes each seed
145	/// with its u32 LE length (the byte stream a single `smith.slice()` consumes).
146	pub fn loadSeeds(a: Allocator, io: std.Io, target: Target, format: SeedFormat) ![]const []const u8 {
147	    var paths: std.ArrayList([]const u8) = .empty;
148	    const own_dir = try std.fs.path.join(a, &.{ corpus_root, @tagName(target) });
149	    listInputs(a, io, own_dir, &paths) catch {};
150	    for (seed_dirs) |d| listInputs(a, io, d, &paths) catch {};
151	    var seeds: std.ArrayList([]const u8) = .empty;
152	    for (paths.items) |path| {
153	        const raw = std.Io.Dir.cwd().readFileAlloc(io, path, a, .limited(max_input_len)) catch continue;
154	        const adapted = (try adaptSeed(target, std.fs.path.basename(path), raw, a)) orelse continue;
155	        if (adapted.len > max_input_len) continue;
156	        switch (format) {
157	            .raw => try seeds.append(a, adapted),
158	            .smith_encoded => {
159	                const len: u32 = std.math.cast(u32, adapted.len) orelse continue;
160	                try seeds.append(a, try std.mem.concat(a, u8, &.{ std.mem.asBytes(&std.mem.nativeToLittle(u32, len)), adapted }));
161	            },
162	        }
163	    }
164	    return seeds.items;
165	}
