167	// ---------------------------------------------------------------------------------------------
168	// Mutation engine (libFuzzer-style mutators; corpus grows on new Feedback signatures).
169	
170	const tokens = [_][]const u8{
171	    "PAR1",
172	    "\x15\x00",
173	    "\x15\x02",
174	    "\x16\x00",
175	    "\x19\x1c",
176	    "\x00",
177	    &@as([4]u8, @splat(0xff)),
178	    "\x00\x00\x00\x00",
179	};
180	const interesting = [_]u64{ 0, 1, 2, 4, 8, 16, 32, 64, 127, 128, 255, 256, 0x7fff, 0x8000, 0xffff, 0x10000, 0x7fffffff, 0x80000000, 0xffffffff, 0x7fffffffffffffff, 0x8000000000000000, std.math.maxInt(u64) };
181	
182	fn mutate(rng: std.Random, gpa: Allocator, buf: *std.ArrayList(u8), corpus: []const []const u8, max_len: usize) !void {
183	    const rounds = 1 + rng.uintLessThan(usize, 5);
184	    for (0..rounds) |_| {
185	        const len = buf.items.len;
186	        switch (rng.uintLessThan(u8, 11)) {
187	            0 => if (len > 0) { // erase a range
188	                const at = rng.uintLessThan(usize, len);
189	                const n = 1 + rng.uintLessThan(usize, @min(len - at, 64));
190	                buf.replaceRangeAssumeCapacity(at, n, &.{});
191	            },
192	            1 => if (len < max_len) { // insert random bytes
193	                const at = rng.uintAtMost(usize, len);
194	                var tmp: [16]u8 = undefined;
195	                const n = 1 + rng.uintLessThan(usize, @min(tmp.len, max_len - len));
196	                rng.bytes(tmp[0..n]);
197	                try buf.insertSlice(gpa, at, tmp[0..n]);
198	            },
199	            2 => if (len > 0) { // flip a bit
200	                buf.items[rng.uintLessThan(usize, len)] ^= @as(u8, 1) << rng.int(u3);
201	            },
202	            3 => if (len > 0) { // random byte
203	                buf.items[rng.uintLessThan(usize, len)] = rng.int(u8);
204	            },
205	            4, 5 => if (len > 0) { // arithmetic / interesting value at width 1/2/4/8
206	                const width = @as(usize, 1) << rng.int(u2);
207	                if (len < width) continue;
208	                const at = rng.uintAtMost(usize, len - width);
209	                var v: u64 = 0;
210	                @memcpy(std.mem.asBytes(&v)[0..width], buf.items[at..][0..width]);
211	                v = if (rng.boolean())
212	                    interesting[rng.uintLessThan(usize, interesting.len)]
213	                else
214	                    v +% @as(u64, @bitCast(@as(i64, rng.intRangeAtMost(i8, -35, 35))));
215	                if (rng.boolean()) v = @byteSwap(v) >> @intCast(64 - 8 * width);
216	                @memcpy(buf.items[at..][0..width], std.mem.asBytes(&v)[0..width]);
217	            },
218	            6 => if (len > 1) { // copy a chunk over another place
219	                const from = rng.uintLessThan(usize, len);
220	                const to = rng.uintLessThan(usize, len);
221	                const n = 1 + rng.uintLessThan(usize, @min(len - @max(from, to), 128));
222	                std.mem.copyForwards(u8, buf.items[to..][0..n], buf.items[from..][0..n]);
223	            },
224	            7, 8 => { // dictionary token, overwrite or insert
225	                const tok = tokens[rng.uintLessThan(usize, tokens.len)];
226	                const at = rng.uintAtMost(usize, len);
227	                if (rng.boolean() and at + tok.len <= len) {
228	                    @memcpy(buf.items[at..][0..tok.len], tok);
229	                } else if (len + tok.len <= max_len) try buf.insertSlice(gpa, at, tok);
230	            },
231	            9 => if (corpus.len > 0) { // splice with another corpus entry
232	                const other = corpus[rng.uintLessThan(usize, corpus.len)];
233	                const cut = rng.uintAtMost(usize, len);
234	                const from = rng.uintAtMost(usize, other.len);
235	                buf.shrinkRetainingCapacity(cut);
236	                try buf.appendSlice(gpa, other[from..@min(other.len, from + (max_len - cut))]);
237	            },
238	            else => if (len > 0) { // repeat a byte
239	                const at = rng.uintLessThan(usize, len);
240	                const n = rng.uintLessThan(usize, @min(64, max_len - @min(max_len, len)) + 1);
241	                try buf.appendNTimes(gpa, buf.items[at], n);
242	            },
243	        }
244	    }
245	}
