247	fn hexName(bytes: []const u8) [16]u8 {
248	    var digest: [20]u8 = undefined;
249	    std.crypto.hash.Sha1.hash(bytes, &digest, .{});
250	    return std.fmt.bytesToHex(digest[0..8].*, .lower);
251	}
