283	fn usage() noreturn {
284	    std.debug.print(
285	        \\usage: zp-fuzz <target> replay <file|dir>...
286	        \\       zp-fuzz <target> run <iters|secs s> [--corpus <dir>...] --out <dir> [--seed N] [--max-len N] [--alloc-cap N] [--timeout S]
287	        \\       zp-fuzz gen-seeds [<corpus-root>]
288	        \\targets: file file-oom page encoding thrift codec
289	        \\
290	    , .{});
291	    std.process.exit(2);
292	}
