294	pub fn main(init: std.process.Init) !void {
295	    const gpa = init.gpa;
296	    const io = init.io;
297	    const arena = init.arena.allocator();
298	    const argv = try init.minimal.args.toSlice(arena);
299	    var args: std.ArrayList([]const u8) = .empty;
300	    var i: usize = 0;
301	    while (i < argv.len) : (i += 1) {
302	        if (std.mem.eql(u8, argv[i], "--timeout") and i + 1 < argv.len) {
303	            i += 1;
304	            hang_seconds = std.fmt.parseInt(u64, argv[i], 10) catch usage();
305	        } else try args.append(arena, argv[i]);
306	    }
307	    if (args.items.len < 2) usage();
308	    if (std.mem.eql(u8, args.items[1], "gen-seeds")) return genSeeds(gpa, io, if (args.items.len > 2) args.items[2] else corpus_root);
309	    if (args.items.len < 3) usage();
310	    const target = std.meta.stringToEnum(Target, args.items[1]) orelse usage();
311	    (try std.Thread.spawn(.{}, watchdog, .{io})).detach();
312	    if (std.mem.eql(u8, args.items[2], "replay")) return replay(gpa, io, target, args.items[3..]);
313	    if (std.mem.eql(u8, args.items[2], "run")) return run(gpa, io, target, args.items[3..]);
314	    usage();
315	}
